const levels=['С нуля','A1','A2','B1'];
const descriptions=['Алфавит, звуки и первые слова','Общение в повседневных ситуациях','Опыт, планы и уверенная практика','Связная речь и собственное мнение'];
let state={done:{},scores:{},drafts:{},written:{},exams:{},days:[]};try{state={...state,...JSON.parse(localStorage.getItem('ellinika-v1')||'{}')}}catch{};
let page='home',filter='Все',lessonId=0,tab='theory',quiz=null,exam=null,cardIndex=0,cardFlip=false;
const app=document.getElementById('app');const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const shuffle=a=>a.map(v=>({v,r:Math.random()})).sort((a,b)=>a.r-b.r).map(x=>x.v);
function save(){const d=new Date().toLocaleDateString('en-CA');if(!state.days.includes(d))state.days.push(d);localStorage.setItem('ellinika-v1',JSON.stringify(state))}
function toast(s){const t=document.getElementById('toast');t.textContent=s;t.style.display='block';setTimeout(()=>t.style.display='none',3500)}
const count=()=>Object.keys(state.done).length;const levelDone=l=>course.filter(x=>x.level===l&&state.done[x.id]).length;
function header(title){return `<header><span>Ваш личный курс греческого</span><span class="pill">${count()} / ${course.length} уроков · ${Math.round(count()/course.length*100)}%</span></header><div class="eyebrow">ΜΑΘΑΙΝΟΥΜΕ ΜΑΖΙ · УЧИМСЯ ВМЕСТЕ</div><h1>${title}</h1>`}
function render(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));if(page==='home')home();if(page==='course')catalog();if(page==='lesson')lesson();if(page==='vocab')vocab();if(page==='exams')exams();if(page==='progress')progress();window.scrollTo(0,0)}
function go(p){speechSynthesis?.cancel();page=p;render()}
function openLesson(id){lessonId=id;tab='theory';quiz=null;go('lesson')}
function home(){const next=course.find(x=>!state.done[x.id])||course[0];app.innerHTML=header('Греческий начинается<br>с одного маленького шага.')+`<p class="muted">От первого «γεια σου» до уверенного общения. В вашем темпе.</p><section class="hero"><div><div class="eyebrow">${count()?'ПРОДОЛЖИМ ВАШ ПУТЬ':'ΚΑΛΩΣ ΗΡΘΑΤΕ · ДОБРО ПОЖАЛОВАТЬ'}</div><h2 style="font-size:28px;margin-top:20px">${next.title}</h2><p>Понятная теория на русском, новые слова и практика. Выделите 20–30 минут на один урок.</p><button class="primary" onclick="openLesson(${next.id})">${count()?'Продолжить обучение':'Начать первый урок'} →</button></div><div class="hero-art" aria-hidden="true"><div class="sun"></div><div class="arch"><strong>α β γ</strong><span>ΕΝΑ ΝΕΟ ΞΕΚΙΝΗΜΑ</span></div><div class="branch">❧</div></div></section><div class="stats"><div class="stat"><span class="icon">✓</span><div><strong>${count()}</strong><small>Уроков завершено</small></div></div><div class="stat"><span class="icon">◇</span><div><strong>${course.filter(l=>state.done[l.id]).length*4}</strong><small>Слов в пройденных уроках</small></div></div><div class="stat"><span class="icon">↗</span><div><strong>${state.days.length}</strong><small>Дней практики</small></div></div></div><div class="section-head"><h2>Ваш маршрут обучения</h2><span class="muted small">4 этапа · ${course.length} уроков</span></div><div class="grid">${levels.map((l,i)=>{const n=course.filter(x=>x.level===l).length;return `<div class="card"><span class="level">${l}</span><h3>${['Первые шаги','Основы общения','Больше свободы','Уверенный греческий'][i]}</h3><p>${descriptions[i]}</p><div class="bar"><div style="width:${levelDone(l)/n*100}%"></div></div><span class="small muted">${levelDone(l)} из ${n} уроков</span><button onclick="filter='${l}';go('course')">Посмотреть уроки →</button></div>`}).join('')}</div><div class="welcome-note">✦ <span>Каждый урок: теория → словарь → аудирование → практика → письмо. Для завершения получите ≥80% в практике, ≥70% в аудировании и сохраните письменную работу с самопроверкой.</span></div>`}
function catalog(){app.innerHTML=header('Урок за уроком — к B1')+`<p class="muted">Все уроки доступны. Рекомендуем проходить их по порядку.</p><div class="filters">${['Все',...levels].map(l=>`<button class="${filter===l?'selected':''}" onclick="filter='${l}';catalog()">${l}</button>`).join('')}</div><div class="lesson-list">${course.filter(l=>filter==='Все'||l.level===filter).map(l=>`<div class="lesson-row"><span class="number">${String(l.id+1).padStart(2,'0')}</span><div class="details"><h3>${l.title}</h3><p>${l.level} · Теория, 4 слова, аудирование, 5 вопросов, письмо</p></div>${state.done[l.id]?'<span class="badge">✓ Пройден</span>':''}<button onclick="openLesson(${l.id})">Открыть →</button></div>`).join('')}</div>`}
function lesson(){const l=course[lessonId];app.innerHTML=header(l.title)+`<div class="section-head"><span class="muted">${l.level} · Урок ${l.id+1} из ${course.length}</span><button onclick="go('course')">← Все уроки</button></div><div class="tabs">${[['theory','01 Теория'],['words','02 Словарь'],['audio','03 Аудирование'],['practice','04 Практика'],['writing','05 Письмо']].map(([k,v])=>`<button class="${tab===k?'selected':''}" onclick="tab='${k}';quiz=null;lesson()">${v}</button>`).join('')}</div><div class="content" id="lessonBody"></div>`;const b=document.getElementById('lessonBody');if(tab==='theory')b.innerHTML=`<div class="panel"><h2>Разберёмся вместе</h2><p class="muted">Прочитайте правило, затем произнесите пример вслух.</p><p class="theory">${l.theory}</p>${l.id===0?alphabet():''}<div class="feedback"><strong lang="el">${l.audio}</strong><br>${l.translation}<br><button aria-label="Прослушать греческий пример" onclick="speak(course[lessonId].audio)">▷ Прослушать произношение</button></div><button class="primary" onclick="tab='words';lesson()">Перейти к словам →</button></div>`;if(tab==='words')b.innerHTML=`<div class="panel"><h2>Четыре слова для практики</h2><p class="muted">Прослушайте слово, произнесите его и запишите по памяти.</p><div class="words">${l.words.map(([el,ru],i)=>`<div class="word"><div><strong lang="el">${el}</strong><small>${ru}</small></div><button aria-label="Прослушать ${el}" onclick="speak(course[lessonId].words[${i}][0])">▷</button></div>`).join('')}</div><div class="actions"><button class="primary" onclick="tab='audio';lesson()">К аудированию →</button></div></div>`;if(tab==='audio')b.innerHTML=`<div class="panel"><h2>Слушаем и понимаем</h2><p>Прослушайте фразу без подсказки, затем запишите её по-гречески. Можно слушать несколько раз. Перевод и текст открывайте после попытки.</p><div class="actions"><button class="primary" onclick="speak(course[lessonId].audio)">▷ Прослушать</button><button onclick="speak(course[lessonId].audio,.65)">▷ Медленнее</button></div><p class="small muted">Синтез речи устройства, греческий голос el-GR. Для аудирования нужен установленный греческий голос.</p><textarea id="dictation" lang="el" placeholder="Запишите услышанное по-гречески…"></textarea><div class="actions"><button class="primary" onclick="checkAudio()">Проверить запись</button></div><div id="audioResult"></div><details><summary>Показать текст и перевод</summary><p lang="el">${l.audio}</p><button aria-label="Прослушать греческий пример" onclick="speak(course[lessonId].audio)">▷ Прослушать произношение</button><p>${l.translation}</p></details></div>`;if(tab==='practice'){quiz={items:questions(l),index:0,right:0,answers:[]};drawQuiz()}if(tab==='writing')writing();}
function normalize(s){return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/ς/g,'σ').replace(/[^\p{L}\p{N}\s]/gu,'').replace(/\s+/g,' ').trim()}
function speak(text,rate=.85){if(!('speechSynthesis' in window)){toast('Синтез речи не поддерживается этим браузером.');return}const voices=speechSynthesis.getVoices();const voice=voices.find(v=>v.lang.toLowerCase().startsWith('el'));if(!voice){toast('Нет греческого голоса. Установите голос «Греческий» в настройках речи устройства и перезагрузите страницу.');return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='el-GR';u.voice=voice;u.rate=rate;u.onerror=()=>toast('Не удалось воспроизвести. Проверьте настройки речи.');speechSynthesis.speak(u)}
function checkAudio(){const l=course[lessonId],a=normalize(document.getElementById('dictation').value),expected=normalize(l.audio);if(!a){toast('Сначала запишите услышанное.');return}let x=a.split(' '),y=expected.split(' ');let dp=Array.from({length:x.length+1},()=>Array(y.length+1).fill(0));for(let i=0;i<=x.length;i++)dp[i][0]=i;for(let j=0;j<=y.length;j++)dp[0][j]=j;for(let i=1;i<=x.length;i++)for(let j=1;j<=y.length;j++)dp[i][j]=Math.min(dp[i-1][j]+1,dp[i][j-1]+1,dp[i-1][j-1]+(x[i-1]===y[j-1]?0:1));const score=Math.round(Math.max(0,1-dp[x.length][y.length]/Math.max(x.length,y.length))*100);state.scores[l.id]={...state.scores[l.id],audio:score};save();document.getElementById('audioResult').innerHTML=`<div class="feedback">${score}% совпадения слов. ${score>=70?'Аудирование зачтено.':'Прослушайте ещё раз и исправьте запись.'}<br><strong>${l.audio}</strong><br>${l.translation}<br><small>При оценке ударения и пунктуация не учитываются; проверяйте их по образцу.</small></div>`;}
function questions(l){return shuffle([{q:l.question,a:l.answer,opts:shuffle([l.answer,...l.wrong]),why:l.theory},...l.words.map(([el,ru])=>({q:`Выберите перевод: ${el}`,a:ru,opts:shuffle([ru,...l.words.filter(w=>w[1]!==ru).map(w=>w[1])]),why:`${el} — ${ru}`}))])}
function drawQuiz(){const target=document.getElementById(exam?'examBody':'lessonBody');if(quiz.index===quiz.items.length){const score=Math.round(quiz.right/quiz.items.length*100);if(exam){state.exams[exam]={score,date:new Date().toLocaleDateString('ru-RU')};save();target.innerHTML=`<div class="panel"><div class="eyebrow">ТЕСТ ${exam}</div><div class="score">${score}%</div><p>${score>=80?'Тест пройден.':'Повторите темы и попробуйте снова.'} Верно ${quiz.right} из ${quiz.items.length}.</p><p>Для полного итога этапа выполните также письменную работу ниже. Балл отражает результат этого теста, а не сертификацию уровня.</p>${quiz.answers.filter(x=>!x.ok).map(x=>`<div class="feedback">${esc(x.q)}<br>Верный ответ: <strong>${esc(x.a)}</strong><br>${esc(x.why)}</div>`).join('')}<button onclick="exam=null;exams()">Вернуться к уровням</button></div>`;return}state.scores[lessonId]={...state.scores[lessonId],practice:score};save();target.innerHTML=`<div class="panel"><div class="score">${score}%</div><p>Верно ${quiz.right} из ${quiz.items.length}. ${score>=80?'Практика зачтена.':'Для зачёта нужно 80%. Повторите материал.'}</p><div class="actions"><button onclick="lesson()">Повторить тест</button><button class="primary" onclick="tab='writing';lesson()">К письменной работе →</button></div></div>`;return}const q=quiz.items[quiz.index];target.innerHTML=`<div class="panel"><div class="eyebrow">ВОПРОС ${quiz.index+1} / ${quiz.items.length}</div><div class="bar"><div style="width:${quiz.index/quiz.items.length*100}%"></div></div><h2 style="margin-top:25px">${esc(q.q)}</h2><p class="muted">Выберите один ответ.</p><div class="answers">${q.opts.map((o,i)=>`<button onclick="answer(${i})">${esc(o)}</button>`).join('')}</div><div id="quizFeedback"></div></div>`}
function answer(i){const q=quiz.items[quiz.index],ok=q.opts[i]===q.a;if(ok)quiz.right++;quiz.answers.push({...q,ok});document.querySelectorAll('.answers button').forEach((b,j)=>{b.disabled=true;if(q.opts[j]===q.a)b.classList.add('correct');else if(j===i)b.classList.add('incorrect')});document.getElementById('quizFeedback').innerHTML=`<div class="feedback">${ok?'✓ Верно':'Попробуем разобраться'}: ${esc(q.a)}<br>${esc(q.why)}</div><button class="primary" onclick="quiz.index++;drawQuiz()">${quiz.index+1===quiz.items.length?'Посмотреть результат':'Следующий вопрос'} →</button>`}
function writing(){const l=course[lessonId];document.getElementById('lessonBody').innerHTML=`<div class="panel"><h2>Ваша письменная практика</h2><p>${l.writing}</p><p class="small muted">Пишите по-гречески. Черновик сохраняется автоматически. Приложение проверяет наличие текста; грамматику и выполнение задания оцените по критериям. Для развёрнутой обратной связи нужна проверка преподавателем.</p><textarea id="draft" lang="el" placeholder="Начните писать здесь…" oninput="state.drafts[lessonId]=this.value;save();document.getElementById('wc').textContent=this.value.trim()?this.value.trim().split(/\s+/).length:0">${esc(state.drafts[l.id]||'')}</textarea><p class="muted small"><span id="wc">${(state.drafts[l.id]||'').trim().split(/\s+/).filter(Boolean).length}</span> слов</p><details><summary>Опорный пример и как его расширить</summary><p lang="el">${l.audio}</p><button aria-label="Прослушать греческий пример" onclick="speak(course[lessonId].audio)">▷ Прослушать произношение</button><p>${l.translation}</p><p>Используйте правило этого урока, замените детали своими и добавьте примеры. Это опорная фраза, а не полный ответ на письменное задание.</p></details><div class="checklist">${['Я выполнил(а) все пункты задания и нужный объём','Я использовал(а) правило и слова урока','Я проверил(а) формы глаголов, артикли и согласование','Я проверил(а) ударения и связность текста'].map((s,i)=>`<label><input type="checkbox" id="criterion${i}" ${state.written[l.id]?'checked':''}> ${s}</label>`).join('')}</div><div class="actions"><button onclick="saveWriting()">Сохранить самопроверку</button><button class="primary" onclick="complete()">Завершить урок ✓</button></div><div id="completion"></div></div>`}
function saveWriting(){if(!/[\u0370-\u03ff]/.test(state.drafts[lessonId]||'')){toast('Добавьте письменный ответ по-гречески.');return false}if(![0,1,2,3].every(i=>document.getElementById('criterion'+i).checked)){toast('Проверьте работу по всем четырём критериям.');return false}state.written[lessonId]=true;save();toast('Письменная работа и самопроверка сохранены.');return true}
function complete(){if(!saveWriting())return;const s=state.scores[lessonId]||{};if((s.practice||0)<80||(s.audio||0)<70){document.getElementById('completion').innerHTML='<div class="feedback">Осталось пройти практику на 80% и аудирование на 70%. Результаты доступны в разделе «Мой прогресс».</div>';return}state.done[lessonId]=true;save();document.getElementById('completion').innerHTML=`<div class="feedback">✓ Урок завершён. Отличная работа!</div>${lessonId<course.length-1?`<button class="primary" onclick="openLesson(${lessonId+1})">Следующий урок →</button>`:'<button onclick="go(\'exams\')">К итоговому тесту B1 →</button>'}`}
function vocab(){app.innerHTML=header('Слова, которые остаются с вами')+`<p class="muted">${course.length*4} слов и выражений. Слушайте произношение и тренируйтесь с карточками.</p><input type="search" id="search" placeholder="Найти по-русски или по-гречески…" oninput="wordList(this.value)"><div class="filters">${['Все',...levels].map(l=>`<button class="${filter===l?'selected':''}" onclick="filter='${l}';cardIndex=0;vocab()">${l}</button>`).join('')}</div><div class="panel" id="flash"></div><div id="wordList"></div>`;flash();wordList('')}
function vocabWords(){return course.filter(l=>filter==='Все'||l.level===filter).flatMap(l=>l.words.map(([el,ru])=>({el,ru,level:l.level})))}
function flash(){const words=vocabWords(),w=words[cardIndex%words.length];document.getElementById('flash').innerHTML=`<div class="eyebrow">КАРТОЧКА ${cardIndex%words.length+1} / ${words.length}</div><h2 style="font-size:30px;margin-top:20px">${cardFlip?w.ru:w.el}</h2><div class="actions"><button onclick="cardFlip=!cardFlip;flash()">Показать ${cardFlip?'слово':'перевод'}</button><button onclick="speak(vocabWords()[cardIndex%vocabWords().length].el)">▷ Слушать</button><button class="primary" onclick="cardIndex++;cardFlip=false;flash()">Следующая →</button></div>`}
function wordList(q){document.getElementById('wordList').innerHTML=`<div class="words">${vocabWords().filter(w=>normalize(w.el+' '+w.ru).includes(normalize(q))).map(w=>`<div class="word"><div><strong>${w.el}</strong><small>${w.ru} · ${w.level}</small></div><button onclick="speak(this.previousElementSibling.querySelector(\'strong\').textContent)" aria-label="Прослушать слово">▷</button></div>`).join('')}</div>`}
function exams(){exam=null;app.innerHTML=header('Проверьте, чему вы научились')+`<p class="muted">Тесты используют материал пройденных этапов. Порог — 80%. Повторные попытки доступны.</p><div class="grid">${levels.map((l,i)=>`<div class="card"><span class="level">${l}</span><h3>Итог этапа</h3><p>${course.filter(x=>levels.indexOf(x.level)<=i).length} тем в банке вопросов · 20 вопросов в попытке</p><p>${state.exams[l]?`Последний результат: ${state.exams[l].score}% · ${state.exams[l].date}`:'Пока не проходили'}</p><button class="primary" onclick="startExam('${l}')">Пройти тест →</button></div>`).join('')}</div><div id="examBody"></div><div class="panel"><h2>Письменный итог этапа</h2><p>Выберите уровень и выполните задание. Оцените каждый критерий от 0 до 5: выполнение задачи, связность, словарь, грамматика. 14 из 20 — ориентир для самопроверки. Это оценка автора работы.</p><select id="writeLevel" onchange="examWriting()">${levels.map(l=>`<option>${l}</option>`).join('')}</select><div id="examWriting"></div></div>`;examWriting()}
function examWriting(){const l=document.getElementById('writeLevel').value;const tasks={'С нуля':'Напишите 5 знакомых греческих слов с ударениями и два приветствия.','A1':'Представьтесь в письме новому другу: имя, возраст, семья, город, увлечения. 40–60 слов.','A2':'Напишите другу о поездке: где были, что делали, что понравилось, планы на следующую поездку. 80–100 слов.','B1':'Напишите мнение: лучше жить в большом городе или небольшом? Приведите два аргумента, пример, другую точку зрения и вывод. 130–160 слов.'};document.getElementById('examWriting').innerHTML=`<p>${tasks[l]}</p><textarea id="examDraft" oninput="state.drafts['exam-${l}']=this.value;save()" placeholder="Ваш ответ по-гречески…">${esc(state.drafts['exam-'+l]||'')}</textarea><div class="actions">${['Задача','Связность','Словарь','Грамматика'].map((k,i)=>`<label>${k} <select id="rubric${i}">${[0,1,2,3,4,5].map(n=>`<option>${n}</option>`).join('')}</select></label>`).join('')}</div><button style="margin-top:20px" onclick="saveExamWriting()">Сохранить письменный итог</button><div id="rubricResult"></div>`}
function saveExamWriting(){const l=document.getElementById('writeLevel').value;if(!/[\u0370-\u03ff]/.test(document.getElementById('examDraft').value)){toast('Напишите ответ по-гречески.');return}const sum=[0,1,2,3].reduce((a,i)=>a+Number(document.getElementById('rubric'+i).value),0);state.exams[l]={...state.exams[l],writing:sum};save();document.getElementById('rubricResult').innerHTML=`<div class="feedback">Самооценка: ${sum}/20. ${sum>=14?'Письменный итог отмечен как выполненный.':'Доработайте слабые критерии.'}</div>`}
function startExam(l){exam=l;quiz={items:shuffle(course.filter(x=>levels.indexOf(x.level)<=levels.indexOf(l)).flatMap(questions)).slice(0,20),index:0,right:0,answers:[]};drawQuiz();document.getElementById('examBody').scrollIntoView({behavior:'smooth'})}
function progress(){app.innerHTML=header('Ваш прогресс — шаг за шагом')+`<p class="muted">Данные хранятся в этом браузере. Сохраняйте резервную копию для переноса на другое устройство.</p><div class="stats"><div class="stat"><div><strong>${Math.round(count()/course.length*100)}%</strong><small>Курса завершено</small></div></div><div class="stat"><div><strong>${Object.keys(state.written).length}</strong><small>Письменных работ с самопроверкой</small></div></div><div class="stat"><div><strong>${Object.values(state.exams).filter(e=>e.score>=80).length}/4</strong><small>Тестов этапов пройдено</small></div></div></div><div class="panel" style="overflow:auto"><table class="table"><thead><tr><th>Урок</th><th>Практика</th><th>Аудирование</th><th>Письмо</th><th>Итог</th></tr></thead><tbody>${course.map(l=>`<tr><td><a href="#" onclick="openLesson(${l.id});return false" style="color:var(--green)">${l.id+1}. ${l.title}</a><br><small>${l.level}</small></td><td>${state.scores[l.id]?.practice??'—'}${state.scores[l.id]?.practice!==undefined?'%':''}</td><td>${state.scores[l.id]?.audio??'—'}${state.scores[l.id]?.audio!==undefined?'%':''}</td><td>${state.written[l.id]?'✓':'—'}</td><td>${state.done[l.id]?'✓ Пройден':'Впереди'}</td></tr>`).join('')}</tbody></table></div>`}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{filter='Все';go(b.dataset.page)});document.querySelector('.brand').onclick=e=>{e.preventDefault();go('home')};document.getElementById('export').onclick=()=>{const blob=new Blob([JSON.stringify({version:1,state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='ellinika-progress.json';a.click();URL.revokeObjectURL(url)};document.getElementById('import').onchange=async e=>{try{const d=JSON.parse(await e.target.files[0].text());if(d.version!==1||!d.state||!Array.isArray(d.state.days)||!['done','scores','drafts','written','exams'].every(k=>d.state[k]&&typeof d.state[k]==='object'&&!Array.isArray(d.state[k])))throw Error();state=d.state;save();render();toast('Прогресс восстановлен.')}catch{toast('Файл прогресса имеет неверный формат.')}e.target.value=''};
render();

function playGreekO(){const C=window.AudioContext||window.webkitAudioContext;if(!C){speak('ό');return}const c=new C(),t=c.currentTime,o=c.createOscillator(),mix=c.createGain();o.type='sawtooth';o.frequency.value=135;mix.gain.setValueAtTime(.001,t);mix.gain.linearRampToValueAtTime(.28,t+.025);mix.gain.setValueAtTime(.28,t+.22);mix.gain.exponentialRampToValueAtTime(.001,t+.38);o.connect(mix);const f1=c.createBiquadFilter(),g1=c.createGain(),f2=c.createBiquadFilter(),g2=c.createGain();f1.type=f2.type='bandpass';f1.frequency.value=500;f1.Q.value=4;g1.gain.value=.8;f2.frequency.value=900;f2.Q.value=4;g2.gain.value=.45;mix.connect(f1);f1.connect(g1);g1.connect(c.destination);mix.connect(f2);f2.connect(g2);g2.connect(c.destination);o.start(t);o.stop(t+.4);o.onended=()=>c.close()}
function speakAlphabet(i){const sounds=['ά','βι','γα','δα','έ','ζα','ί','θι','ί','κα','λα','μα','να','ξι','ό','πα','ρα','σα','τα','ί','φι','χι','ψι','ό'];if(i===14||i===23)playGreekO();else speak(sounds[i])}
function alphabet(){return '<h3>Все 24 буквы</h3><p class="small muted">Русская запись приблизительна. Слушайте буквы и слова с греческим голосом.</p><div class="words">'+[['Α α','альфа · а'],['Β β','вита · в'],['Γ γ','гамма · фрикативный г / й'],['Δ δ','дельта · звонкий межзубный'],['Ε ε','эпсилон · э'],['Ζ ζ','зита · з'],['Η η','ита · и'],['Θ θ','тита · глухой межзубный'],['Ι ι','йота · и'],['Κ κ','каппа · к'],['Λ λ','ламда · л'],['Μ μ','ми · м'],['Ν ν','ни · н'],['Ξ ξ','кси · кс'],['Ο ο','омикрон · о'],['Π π','пи · п'],['Ρ ρ','ро · р'],['Σ σ ς','сигма · с'],['Τ τ','таф · т'],['Υ υ','ипсилон · и'],['Φ φ','фи · ф'],['Χ χ','хи · х'],['Ψ ψ','пси · пс'],['Ω ω','омега · о']].map(([a,b],i)=>'<div class="word"><div><strong>'+a+'</strong><small>'+b+'</small></div><button aria-label="Прослушать звук" onclick="speakAlphabet('+i+')">▷</button></div>').join('')+'</div>'}
